# v2.5.4 tests: pid marker + run-log pid, hooks for every role. Sourced by run-tests.sh after v253 (uses $RN $PL $SID $HK expect).
PD="$T/pd"; cp -r "$RN" "$PD"
expect 0 "implement run log has pid/eng_run_pid; no .running marker after finish" bash -c "cd '$PD' && python3 .eng/bin/eng-run implement $PL $SID >/dev/null && f=\$(ls -t thoughts/shared/runs/*implement*.md | grep -v running | head -1) && grep -Eq '^pid: [1-9][0-9]*$' \$f && grep -Eq '^eng_run_pid: [1-9][0-9]*$' \$f && ! ls thoughts/shared/runs/*.running.md 2>/dev/null | grep -q ."
expect 0 "code-review run log has pid; no marker after finish" bash -c "cd '$PD' && python3 .eng/bin/eng-run code-review $SID --allow-self-review >/dev/null 2>&1 && grep -Eq '^pid: [1-9][0-9]*$' \$(ls -t thoughts/shared/runs/*code-review*.md | head -1) && ! ls thoughts/shared/runs/*.running.md 2>/dev/null | grep -q ."
expect 0 "marker exists with status running + pid while runner runs, gone after" bash -c "cd '$PD' && rm -f sent && (FAKE_SLEEP=2 FAKE_SENTINEL=\$PWD/sent python3 .eng/bin/eng-run implement $PL $SID >/dev/null 2>&1 &) ; for i in \$(seq 50); do test -f sent && break; sleep 0.1; done; m=\$(ls thoughts/shared/runs/*.running.md) && grep -qx 'status: running' \$m && p=\$(sed -n 's/^pid: //p' \$m) && [ \"\$p\" -gt 0 ] && grep -q '^eng_run_pid: [1-9]' \$m && grep -qx 'role: implement' \$m && grep -q '^run_log: thoughts/shared/runs/.*implement.*\\.md' \$m && for i in \$(seq 100); do test -f \$m || break; sleep 0.1; done; ! test -f \$m && grep -qx \"pid: \$p\" \$(ls -t thoughts/shared/runs/*implement*.md | head -1)"
expect 0 "ENG_PID in implement hook env" bash -c "cd '$HK' && rm -f hook.env && python3 .eng/bin/eng-run implement $PL $SID >/dev/null && grep -Eq '^ENG_PID=[1-9][0-9]*$' hook.env && grep -Eq '^ENG_ENG_RUN_PID=[1-9][0-9]*$' hook.env"
expect 0 "implement_on_complete alone does not fire for code-review" bash -c "cd '$HK' && rm -f hook.env && python3 .eng/bin/eng-run code-review $SID --allow-self-review >/dev/null 2>&1; ! test -f hook.env"
GH="$T/gh"; cp -r "$RN" "$GH"
(cd "$GH" && sed -i '/^\[hooks\]/,/^\[/{/^implement_on_complete/d}' .eng/runners.toml && sed -i '/^\[hooks\]/a on_complete = '"'"'env | grep "^ENG_" | sort > hook.env'"'" .eng/runners.toml)
expect 0 "general on_complete fires for code-review with ENG_ROLE + ENG_PID" bash -c "cd '$GH' && python3 .eng/bin/eng-run code-review $SID --allow-self-review >/dev/null 2>&1; grep -qx 'ENG_ROLE=code-review' hook.env && grep -Eq '^ENG_PID=[1-9]' hook.env"
expect 0 "role-specific code_review_on_complete wins over on_complete" bash -c "cd '$GH' && rm -f hook.env && sed -i '/^\[hooks\]/a code_review_on_complete = \"touch cr.hook\"' .eng/runners.toml && python3 .eng/bin/eng-run code-review $SID --allow-self-review >/dev/null 2>&1; test -f cr.hook && ! test -f hook.env"
expect 0 "dry-run prints pid marker path, writes no marker" bash -c "cd '$PD' && python3 .eng/bin/eng-run implement $PL $SID --dry-run | grep -q '^# pid marker (not written): thoughts/shared/runs/.*\\.running\\.md' && ! ls thoughts/shared/runs/*.running.md 2>/dev/null | grep -q ."
expect 0 "eng-check passes while a run is in progress (marker present)" bash -c "cd '$PD' && rm -f sent && (FAKE_SLEEP=2 FAKE_SENTINEL=\$PWD/sent python3 .eng/bin/eng-run implement $PL $SID >/dev/null 2>&1 &) ; for i in \$(seq 50); do test -f sent && break; sleep 0.1; done; ls thoughts/shared/runs/*.running.md >/dev/null && python3 .eng/bin/eng-check . >/dev/null; r=\$?; sleep 2.5; [ \$r = 0 ]"
